// Normalize and deduplicate lead
const items = $input.all();
const normalized = [];

for (const item of items) {
  const body = item.json.body || item.json;

  // Normalize fields
  const lead = {
    first_name: '',
    last_name: '',
    email: '',
    phone: '',
    city: body.city || null,
    state: body.state || null,
    vertical: body.vertical || 'solar',
    category: body.category || '',
    energy_bill: body.energy_bill || body.bill_amount || null,
    message: body.message || body.comments || body.notes || '',
    utm_source: body.utm_source || null,
    utm_medium: body.utm_medium || null,
    utm_campaign: body.utm_campaign || null,
    utm_content: body.utm_content || null,
    source: body.source || body.utm_source || 'website',
    avails_id: `AS-${Date.now()}-${Math.random().toString(36).substr(2, 6)}`,
    created_at: new Date().toISOString()
  };

  // Parse name
  const fullName = body.name || body.full_name || '';
  const nameParts = fullName.trim().split(' ');
  lead.first_name = nameParts[0] || 'Contato';
  lead.last_name = nameParts.slice(1).join(' ') || '';

  // Parse email
  lead.email = (body.email || '').toLowerCase().trim();

  // Normalize phone to E.164
  let phone = body.phone || body.phone_number || '';
  phone = phone.replace(/[^\d+]/g, '');
  if (phone.startsWith('+')) {
    lead.phone = phone;
  } else if (phone.startsWith('55')) {
    lead.phone = '+' + phone;
  } else if (phone.startsWith('0')) {
    lead.phone = '+55' + phone.substring(1);
  } else if (phone.length >= 10) {
    lead.phone = '+55' + phone;
  }

  // Normalize energy bill
  if (lead.energy_bill) {
    lead.energy_bill = parseFloat(String(lead.energy_bill).replace(/[^\d.]/g, '')) || null;
  }

  normalized.push({ json: lead });
}

return normalized;

// Check if contact already exists in Nutshell
const items = $input.all();
const results = [];

for (const item of items) {
  const lead = item.json;
  const existing = item.json._existing || [];
  const alreadyExists = existing.length > 0 && existing[0].totalResults > 0;

  results.push({
    json: {
      ...lead,
      already_exists: alreadyExists,
      existing_contact_id: alreadyExists ? existing[0]?.results?.[0]?.id : null
    }
  });
}

return results;

